package com.honorablemobile

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
class VideoColorAllReviewTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun colorActivity():HonorableVideoEditorActivity=activity().also{a->val p=get(a,"project")as VideoEditProject;val original=p.segments[0];p.restore(listOf(original.copy(title="First",grade=VideoGrade(exposure=-.5f)),original.copy(startMs=1000,endMs=4000,speed=2f,title="Source",grade=VideoGrade(.5f,1.2f,.8f,.2f,-.1f)),original.copy(startMs=2000,endMs=5000,title="Third",grade=VideoGrade(saturation=.5f))),soundtrack=p.soundtrack);set(a,"selectedClip",1)}
 private fun confirmation(a:HonorableVideoEditorActivity):AlertDialog=dialog().also{set(a,"colorAllConfirmation",it);set(a,"captionReviewDialogs",linkedSetOf(it))}
 private fun commit(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoCaptionReviewState)=call(a,"commitColorAllReview",d,r,get(a,"project"),get(a,"selectedClip"))as Boolean
 @Test fun copiesOnlyChosenGradeAcrossAllClipsWithOneUndo(){val a=colorActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val music=p.soundtrack;val duration=VideoPlaybackTime.durationUs(old);val chosen=old[1].grade;val r=capture(a);val d=confirmation(a);assertTrue(commit(a,d,r));assertEquals(old.map{it.copy(grade=chosen)},p.segments);assertEquals(duration,VideoPlaybackTime.durationUs(p.segments));assertSame(music,p.soundtrack);assertEquals(old.map{it.captionSourceUri},p.segments.map{it.captionSourceUri});assertNull(get(a,"colorAllConfirmation"));assertTrue(p.undo());assertEquals(old,p.segments);assertFalse(p.canUndo);assertTrue(p.redo());assertTrue(p.segments.all{it.grade==chosen})}
 @Test fun alreadyMatchingColorsDoNotCreateUndo(){val a=colorActivity();val p=get(a,"project")as VideoEditProject;val grade=p.segments[1].grade;p.restore(p.segments.map{it.copy(grade=grade)},soundtrack=p.soundtrack);val old=p.segments;val r=capture(a);val d=confirmation(a);assertFalse(commit(a,d,r));assertSame(old,p.segments);assertFalse(p.canUndo);assertNull(get(a,"colorAllConfirmation"))}
 @Test fun untrackedDismissedOrReplacedConfirmationCannotApply(){for(flag in listOf("untracked","dismissed","replaced")){val a=colorActivity();val p=get(a,"project")as VideoEditProject;val old=p.segments;val r=capture(a);val d=confirmation(a);when(flag){"untracked"->set(a,"captionReviewDialogs",linkedSetOf<AlertDialog>());"dismissed"->showing(d,false);else->set(a,"colorAllConfirmation",dialog())};assertFalse(flag,commit(a,d,r));assertSame(old,p.segments);assertFalse(p.canUndo)}}
 @Test fun staleForegroundGenerationSourceRangeSessionRecoveryMusicAndGradeReject(){for(flag in listOf("pause","generation","source","duration","range","mode","recovery","busy","music","grade")){val a=colorActivity();val p=get(a,"project")as VideoEditProject;val r=capture(a);val d=confirmation(a);when(flag){"pause"->set(a,"workspaceActive",false);"generation"->set(a,"captionReviewGeneration",r.generation+1);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"range"->set(a,"selectedClip",0);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"recovery"->set(a,"recoveryBytes",byteArrayOf(1));"busy"->set(a,"saving",true);"music"->p.setSoundtrack(p.soundtrack!!.copy(volume=.5f));else->p.setGrade(1,VideoGrade(warmth=.5f))};val before=p.segments;assertFalse(flag,commit(a,d,r));assertSame(before,p.segments);assertNull(get(a,"colorAllConfirmation"))}}
 @Test fun oldOwnerCannotConsumeNewOrReviveAfterUndo(){val a=colorActivity();val p=get(a,"project")as VideoEditProject;val old=confirmation(a);val current=confirmation(a);val r=capture(a);assertFalse(commit(a,old,r));assertSame(current,get(a,"colorAllConfirmation"));assertTrue(commit(a,current,r));assertFalse(commit(a,current,r));assertTrue(p.undo());assertEquals(true,call(a,"canApplyCaptionReview",r));assertFalse(commit(a,current,r));assertFalse(p.canUndo);assertTrue(p.canRedo)}
 @Test fun foreignProjectOrIndexCannotUseCurrentApproval(){for(foreign in listOf(false,true)){val a=colorActivity();val p=get(a,"project")as VideoEditProject;val before=p.segments;val r=capture(a);val d=confirmation(a);val other=VideoEditProject(5000);assertEquals(false,call(a,"commitColorAllReview",d,r,if(foreign)other else p,if(foreign)1 else 0));assertSame(before,p.segments);assertFalse(p.canUndo);assertFalse(other.canUndo);assertNull(get(a,"colorAllConfirmation"))}}
 @Test fun copiedColorAndAllOtherClipMetadataSurviveDraftCodec(){val a=colorActivity();val p=get(a,"project")as VideoEditProject;val r=capture(a);val d=confirmation(a);val grade=p.segments[1].grade;assertTrue(commit(a,d,r));val selected=p.segments[1];val draft=VideoDraft(5000,p.segments,1,selected.startMs,selected.startMs,selected.endMs,soundtrack=p.soundtrack);val restored=requireNotNull(VideoDraftCodec.decode(VideoDraftCodec.encode(draft),5000));assertEquals(draft,restored);assertTrue(restored.segments.all{it.grade==grade});assertEquals("Source",restored.segments[1].title);assertEquals("content://synthetic/subtitles",restored.segments[1].captionSourceUri)}
 @Test fun pausedOrRecoveringColorAllEntryReturnsBeforeWidgets(){for(recovery in listOf(false,true)){val a=colorActivity();if(recovery)set(a,"recoveryBytes",byteArrayOf(1))else set(a,"workspaceActive",false);call(a,"copyGradeToAll");assertNull(get(a,"colorAllConfirmation"));assertNull(get(a,"captionReviewDialogs"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
}
